// logger, usage: log(this, "");
const log = global.get('logger');

/*    From cheapes-energy-hours macro
      See: https://github.com/TheFes/cheapest-energy-hours/blob/main/documentation/1-source_data.md#data-provider-settings

      - None (default selection)
      - Zonneplan
      - Amber Electric
      - EasyEnergy, EnergyZero (core)
      - ENTSO-E
      - Frank Energie
      - Grid Clock
      - GE-Spot
      - Grid Clock (40 bidzones)
      - Tibber, Nordpool (core)
      - Tibber (custom)
      - Nordpool (custom)
      - PVPC (Spain)
      - Octopus Energy
      - Omie
*/

switch (msg.dynamic.data_source) {
      case "None":
            // Handle the 'None' case (e.g., no supplier selected or data is unavailable)
            log(this,"No data source selected.");
            // Add config here...
            break;

      case "Zonneplan":
            // Code for Zonneplan (a Dutch energy supplier)
            // when using: https://github.com/fsaris/home-assistant-zonneplan-one
            log(this,"Processing Zonneplan data.");
            // Add config here...
            // Zonneplan publishes quarter-hourly tariffs on their own entity, with the price
            // nested in price_tax_included.amount. A nested value can not be reached with
            // value_key (the macro reads item[value_key]), so the list is reshaped here and
            // handed to the macro through price_data. Needs Cheapest Energy Hours >= v6.0.0.
            // Falls back to the legacy hourly attributes when the quarter-hourly entity is
            // not available. Both shapes use the same 1e-7 scale, so value_conversion holds
            // for either of them.
            msg.dynamic.template_prefix =
`{%- set zp = namespace(list=[]) -%}
{%- set q = state_attr('sensor.zonneplan_current_quarter_hourly_electricity_tariff', 'forecast') -%}
{%- for i in q or [] -%}
{%- set zp.list = zp.list + [{'start': i['start_date'], 'price': i['price_tax_included']['amount']}] -%}
{%- endfor -%}
{%- if not q -%}
{%- for i in state_attr('sensor.zonneplan_current_electricity_tariff', 'forecast') or [] -%}
{%- set zp.list = zp.list + [{'start': i['datetime'], 'price': i['electricity_price']}] -%}
{%- endfor -%}
{%- endif -%}`;
            msg.dynamic.price_data = 'zp.list';
            msg.dynamic.time_key = 'start';
            msg.dynamic.value_key = 'price';
            msg.dynamic.value_conversion = 10000000; // whole currency / kWh
            break;

      case "Amber Electric":
            // Code for Amber Electric (Australian energy retailer)
            log(this,"Processing Amber Electric data.");
            // Add config here...
            msg.dynamic.attr_all='forecasts'; 
            msg.dynamic.time_key='start_time'; 
            msg.dynamic.value_key='per_kwh';
            break;

      case "EasyEnergy, EnergyZero (core)":
            // Code for EasyEnergy and EnergyZero (core/default implementation)
            log(this,"Processing EasyEnergy/EnergyZero core data.");
            // Add config here...
            break;

      case "ENTSO-E":
            // Code for ENTSO-E (European Network of Transmission System Operators for Electricity)
            log(this,"Processing ENTSO-E data.");
            // Add config here...
            msg.dynamic.attr_today='prices_today'; 
            msg.dynamic.attr_tomorrow='prices_tomorrow'; 
            msg.dynamic.time_key='time';
            msg.dynamic.value_key='price';
            break;

      case "Frank Energie":
            // Code for Frank Energie (Dutch energy supplier)
            log(this,"Processing Frank Energie data.");
            // Add config here...
            msg.dynamic.sensor = 'sensor.frank_energie_prijzen_gemiddelde_elektriciteitsprijs_alle_uren_all_in'; // when using: https://github.com/HiDiHo01/home-assistant-frank_energie
            msg.dynamic.attr_all = 'prices'; 
            msg.dynamic.time_key = 'from'; 
            msg.dynamic.value_key = 'price';
            break;

      case "GE-Spot":
            // Code for GE-Spot (Global Electric Spot price)
            log(this,"Processing GE-Spot data.");
            // Add config here...
            msg.dynamic.attr_today = 'today_hourly_prices'; // using the hourly version. today_interval_prices is per 15 mins
            msg.dynamic.attr_tomorrow = 'tomorrow_hourly_prices'; // using the hourly version
            msg.dynamic.time_key = 'time'; 
            msg.dynamic.value_key = 'value';
            break;

      case "Grid Clock":
            // Code for Grid Clock (your own gridclock.eu service), zone Default
            log(this, "Processing Grid Clock data.");
            // 'Generate templates' below only forwards a fixed allow-list of
            // msg.dynamic keys to the macro call - value_conversion isn't one of
            // them, so setting it silently did nothing (confirmed: prices stayed
            // exactly 100x too high). Grid Clock's total is ct/kWh; the macro
            // expects EUR/kWh like the other sources. Converting it ourselves via
            // template_prefix, the same technique the Zonneplan case above uses
            // to reshape+convert its own raw data.
            msg.dynamic.template_prefix =
                  `{%- set gc = namespace(list=[]) -%}
            {%- for i in state_attr('sensor.grid_clock_default_prices', 'prices') or [] -%}
            {%- set gc.list = gc.list + [{'start': i['startsAt'], 'price': i['total'] / 100}] -%}
            {%- endfor -%}`;
            msg.dynamic.price_data = 'gc.list';
            msg.dynamic.time_key = 'start';
            msg.dynamic.value_key = 'price';
            break;

      case "Nordpool (core)":
            // Code for Nordpool (core/default implementation)
            log(this, "Processing Nordpool core data.");
            // Add config here...
            msg.dynamic.sensor = 'sensor.nordpool_ceh_prices';
            msg.dynamic.attr_today = 'today';
            msg.dynamic.attr_tomorrow = 'tomorrow';
            msg.dynamic.time_key = 'start';
            msg.dynamic.value_key = 'value';
            msg.dynamic.datetime_in_data = true; // datetime is in the data
            break;

      case "Tibber (core)":
            // Code for Tibber (core/default implementation)
            log(this,"Processing Tibber core data.");
            // Add config here...
            msg.dynamic.sensor = 'sensor.tibber_ceh_prices';
            msg.dynamic.attr_today = 'today';
            msg.dynamic.attr_tomorrow = 'tomorrow';
            msg.dynamic.time_key = 'start';
            msg.dynamic.value_key = 'value';
            msg.dynamic.datetime_in_data = true; // datetime is in the data
            break;

      case "Tibber (custom)":
            // Code for a custom Tibber setup/configuration
            log(this,"Processing Tibber custom data.");
            // Add config here...
            msg.dynamic.attr_today = 'today';
            msg.dynamic.attr_tomorrow = 'tomorrow';
            msg.dynamic.datetime_in_data = false;
            break;

      case "Nordpool (custom)":
            // Code for a custom Nordpool setup/configuration
            log(this,"Processing Nordpool custom data.");
            // Add config here...
            break;

      case "PVPC (Spain)":
            // Code for PVPC (Voluntary Price for Small Consumers in Spain)
            log(this,"Processing Spanish PVPC data.");
            // Add config here...
            break;

      case "Octopus Energy":
            // Code for Octopus Energy (UK/international energy supplier)
            log(this,"Processing Octopus Energy data.");
            // Add config here...
            msg.dynamic.attr_all = 'rates'; 
            msg.dynamic.value_key = 'value_incl_vat';
            break;

      case "Omie":
            // Code for Omie (Iberian Energy Market Operator)
            log(this,"Processing Omie data.");
            // Add config here...
            break;

      default:
            // Code to execute if the supplier does not match any of the above cases
            node.warn(`Unknown supplier: ${msg.dynamic.data_source}. Using default logic.`);
            log(this,`Unknown supplier: ${msg.dynamic.data_source}. Using default logic.`);
            // Add default error handling...
}

log(this, "Performing API calls...");

return msg;

// final template initialization
msg.dynamic.template_all = "";

// temporary template parts
let template_start = "";
let template_common = [];
let template_all = [];
let template_end = "";

// load the macro
// A data source may inject raw Jinja through msg.dynamic.template_prefix. That is used when
// the source data has to be reshaped before it can be handed to the macro — see the Zonneplan
// case in 'Data source settings'.
const template_lines = [`{% from 'cheapest_energy_hours.jinja' import cheapest_energy_hours %}`];
if (msg.dynamic.template_prefix) {
    template_lines.push(msg.dynamic.template_prefix);
}
template_lines.push(`{{ cheapest_energy_hours(`);
template_start = template_lines.join("\n") + "\n";
template_end = `) | to_json }}`;

// collect arguments | strings
const stringKeys = [
    'sensor',
    'attr_all',
    'value_key',
    'attr_today',
    'attr_tomorrow',
    'time_key',
    'source_settings'
];

stringKeys.forEach(key => {
    if (msg.dynamic[key] !== undefined) {
        template_common.push(`${key}='${msg.dynamic[key]}'`);
    }
});

// collect arguments | boolean, integer
const otherKeys = [
    'datetime_in_data',
    'data_minutes',
    'price_data', // a Jinja variable name, so it must be emitted unquoted
];

otherKeys.forEach(key => {
    if (msg.dynamic[key] !== undefined) {
        template_common.push(`${key}=${msg.dynamic[key]}`);
    }
});

// copy common items
template_all = [...template_common];

// collect all hours | via extra call
template_all.push(`hours="all"`);
template_all.push(`include_tomorrow=true`);
template_all.push(`mode="all"`);

/**
 * Formats an array of strings into a single string:
 * - Each item starts with 4 spaces.
 * - Each item ends with a comma, except the last one.
 * - Items are separated by a newline.
 */
function formatTemplateArray(array) {
    if (!array || array.length === 0) {
        return "";
    }

    const indent = "    "; 

    const formatted_lines = array.map((element, index) => {
        const suffix = (index < array.length - 1) ? "," : "";
        return `${indent}${element}${suffix}`;
    });

    return formatted_lines.join('\n');
}

// generate string templates
const template_all_string = formatTemplateArray(template_all);

// done
msg.dynamic.template_all = `${template_start}${template_all_string}${template_end}`;

return msg;

// Logger
const log = global.get("logger");
log(this,`${msg.target} strategy`);

// Status
node.status({fill:"green",shape:"dot",text:`${msg.target}`});

return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}

// logger, usage: log(this, "");
const log = global.get('logger');

const dynamicData = msg.dynamic;

// Helper to check for errors in the object
const isInvalid = (data) => {
    if (!data) return true;
    // Check if the stringified object contains "error"
    return JSON.stringify(data).toLowerCase().includes("error");
};

if (isInvalid(dynamicData) || (dynamicData && dynamicData.no_data)) {
    // Explain issue
    log(this, "Invalid data received, clearing cache", "warn");
    // Clear cache
    flow.set("cached_dynamic_data", undefined);
} else {
    // Cache on success
    log(this, "Caching `msg.dynamic`");
    // Save the entire object to flow context
    flow.set("cached_dynamic_data", dynamicData);
}

return msg;

const handle = global.get('unhandledException');

handle(this);

return msg;

// Check if cache can be used or a new call to Data Source is required
const log = global.get('logger');

// Retrieve stored data from flow context
const cachedData = flow.get("cached_dynamic_data");

// The cache holds the fetched price list itself, so it is only valid for the data
// source it was fetched from. msg.dynamic.data_source is the CURRENT dropdown value
// (set by the 'Source' node just before); cachedData.data_source is the value at the
// time of caching. Without this check, switching the dropdown kept serving the old
// source's prices until the next scheduled cache clear (00:01 / 13:15 / 15:00),
// while the dashboard label already showed the new source.
const currentSource = msg.dynamic && msg.dynamic.data_source;
const sourceMatches = cachedData && cachedData.data_source === currentSource;

if (cachedData && !sourceMatches) {
    log(this, `*CACHE INVALID* cached source '${cachedData.data_source}' != selected '${currentSource}', refetching`);
    flow.set("cached_dynamic_data", undefined);
}

// After 13:00 the cache only counts if it already covers tomorrow.
// Day-ahead prices arrive somewhere after ~13:00; without this, a list fetched
// at 13:16 (before publication) was reused until the 15:01 or 00:01 cache clear,
// so the Timed/Dynamic view showed no prices for tomorrow while the source had them.
const coversTomorrow = (c) => {
    const a = c && c.data_all;
    if (!a || !a.start || !a.hours) return false;
    const end = new Date(new Date(a.start).getTime() + a.hours * 3_600_000);
    const midnight = new Date();
    midnight.setHours(24, 0, 0, 0);
    return end > midnight;
};
const awaitingTomorrow = new Date().getHours() >= 13 && !coversTomorrow(cachedData);

// Determine cache hit
if (cachedData && sourceMatches && !awaitingTomorrow) {
    // Cache HIT
    node.status({ fill: "green", shape: "dot", text: `Cache hit (${currentSource})` });
    log(this, `*CACHE HIT* using stored tariff data (${currentSource})`);

    // Attach cached data to the message so following nodes can use it
    msg.dynamic = cachedData;

    // Output #1
    return [msg, null];

} else {
    // Cache MISS (no cache, other source, or still waiting for tomorrow's prices)
    if (awaitingTomorrow && cachedData && sourceMatches) {
        log(this, "*CACHE STALE* no prices for tomorrow yet, refetching");
    }
    node.status({ fill: "yellow", shape: "ring", text: awaitingTomorrow && cachedData ? `Waiting for tomorrow (${currentSource})` : `Cache miss (${currentSource})` });

    // Output #2
    return [null, msg];
}

// Clear cache
flow.set("cached_dynamic_data", undefined);
return msg;

// logger, usage: log(this, "");
const log = global.get('logger');

// Conversion
const CONVERSION_RATE = parseFloat(RED.util.getMessageProperty(msg, "dynamic.value_conversion")) || 1;

// Check if the list exists and is an array to prevent errors
if (msg.dynamic && msg.dynamic.data_all && Array.isArray(msg.dynamic.data_all.list)) {

    // Create a new array where each value is multiplied
    if (Array.isArray(msg.dynamic.data_all?.list)) {
        msg.dynamic.data_all.list = msg.dynamic.data_all.list.map(v => v / CONVERSION_RATE * 100); // cents
    }

    // Update other fields
    if (msg.dynamic.data_all?.average) {
        msg.dynamic.data_all.average = parseInt(msg.dynamic.data_all.average / CONVERSION_RATE * 100); // cents
    }
    if (msg.dynamic.data_all?.weighted_average){
        msg.dynamic.data_all.weighted_average = parseInt(msg.dynamic.data_all.weighted_average / CONVERSION_RATE * 100); // cents
    }
    if (msg.dynamic.data_all?.min) {
        msg.dynamic.data_all.min = parseInt(msg.dynamic.data_all.min / CONVERSION_RATE * 100); // cents
    }
    if (msg.dynamic.data_all?.max) {
        msg.dynamic.data_all.max = parseInt(msg.dynamic.data_all.max / CONVERSION_RATE * 100); // cents
    }
} else {
    // No usable price data from the selected source (integration missing, sensor empty,
    // macro error). Publish an EMPTY set instead of stopping: stopping left the previous
    // source's prices on sensor.hbc_energy_prices_data, so the chart kept showing them.
    // 'Cache data source' does not cache this, so the next run tries the source again.
    log(this, "*no price data* from the selected data source - publishing an empty set", "warn");
    msg.dynamic = msg.dynamic || {};
    msg.dynamic.no_data = true;
    msg.dynamic.data_all = { list: [], list_marked: [], average: 0, mark_now: 'No data', start: 'Unknown', datapoints_per_hour: 0, net_spread_avg: 0, gross_spread_avg: 0 };
}

return msg;
